#ifndef CHROME_BROWSER_THEMES_HALCYON_THEME_H_
#define CHROME_BROWSER_THEMES_HALCYON_THEME_H_

#include "base/no_destructor.h"
#include "chrome/browser/themes/theme_service.h"
#include "third_party/skia/include/core/SkColor.h"

namespace halcyon {

// HalcyonTheme — the Halcyon theme service.
//
// Halcyon does not use the upstream Chrome theme system's
// "AutogeneratedTheme" or "BrowserThemePack" — instead, this class is a
// ThemeService subclass that returns Halcyon's palette colors for any
// of upstream's color_id values. The mapping is done in GetColor(), below.
//
// The Halcyon theme is also used to feed the NativeTheme (so that Views
// see the right colors) — see HalcyonNativeTheme::GetSystemColor() in
// halcyon_native_theme.cc.
//
// The Halcyon theme's user preference is stored as a string:
// "system", "light", or "dark". When "system", the theme follows the OS
// preference. The HalcyonSettings UI's "Appearance → Theme" select is the
// only way to change it (other than the OS theme changing in "system"
// mode).
//
// HalcyonTheme is a singleton (Halcyon does not have per-profile theming).
// The upstream ThemeServiceFactory::GetForProfile returns this singleton
// when enable_halcyon is true.

class HalcyonTheme : public ThemeService {
 public:
  HalcyonTheme();
  ~HalcyonTheme() override;

  // Disallow copy/assign (singleton).
  HalcyonTheme(const HalcyonTheme&) = delete;
  HalcyonTheme& operator=(const HalcyonTheme&) = delete;

  // ThemeService:
  SkColor GetColor(int color_id, bool use_dark) const;

  // Convenience wrappers used by the Halcyon Views to avoid the color_id
  // enum.
  bool ShouldUseDarkColors() const;

  // Forces the theme into light or dark, regardless of the user's
  // preference. Used by the Cove (which always uses dark) and by tests.
  void SetForcedDark(bool dark) { forced_dark_ = dark; forced_light_ = false; }
  void SetForcedLight(bool light) { forced_light_ = light; forced_dark_ = false; }
  void ClearForced() { forced_dark_ = false; forced_light_ = false; }

  // Singleton accessor.
  static HalcyonTheme& Get();

  // NOTE: For a full build, this class would need to implement (or override)
  // the remaining pure-virtual methods of ThemeService, including Init(),
  // UsingExtensionTheme(), GetThemeID(), etc. For the Halcyon design
  // project, the most important override is GetColor — the rest are
  // stubbed out in halcyon_theme.cc with comments indicating what they
  // should do. See chrome/browser/themes/theme_service.h for the upstream
  // interface.

 private:
  friend class base::NoDestructor<HalcyonTheme>;

  bool forced_dark_ = false;
  bool forced_light_ = false;
};

}  // namespace halcyon

#endif  // CHROME_BROWSER_THEMES_HALCYON_THEME_H_
